"use client";

import { useMemo, useState } from "react";
import { useForm, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type CartonConfiguration } from "@/lib/store";
import { cartonConfigSchema, type CartonConfigFormValues } from "@/lib/schemas";
import { SortableTable } from "@/components/ui/sortable-table";
import { InfoTip } from "@/components/ui/info-tip";

function StatusBadge({ used }: { used: boolean }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
      used ? "bg-amber-950 text-amber-400 border border-amber-900" : "bg-green-950 text-green-400 border border-green-900"
    }`}>
      {used ? "Used in Packing Run" : "Available"}
    </span>
  );
}

function AddConfigDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const rawMaterials = useStore((s) => s.rawMaterials);
  const addCartonConfiguration = useStore((s) => s.addCartonConfiguration);

  // Packaging cost build-up (BRS v1.2 sec 1.1; Frontend spec v2.2 sec 5.13
  // "Carton Configuration cost preview"). Grams-per-unit is always in
  // grams; the underlying Raw Material's avgUnitCost is per its stock
  // `unit`. Assume that unit is "kg" unless it is literally "g".
  const costPerGram = (rawMaterialId: string) => {
    const rm = rawMaterials.find((r) => r.id === rawMaterialId);
    if (!rm) return 0;
    return rm.unit === "g" ? rm.avgUnitCost : rm.avgUnitCost / 1000;
  };

  const { register, handleSubmit, control, watch, reset, formState: { errors, isSubmitting } } = useForm<CartonConfigFormValues>({
    resolver: zodResolver(cartonConfigSchema),
    defaultValues: { name: "", wrapperId: wrappers[0]?.id ?? "", packetsPerBox: 12, boxId: boxes[0]?.id ?? "", boxesPerCarton: 4 },
  });

  const name = watch("name");
  const wrapperId = watch("wrapperId");
  const boxId = watch("boxId");
  const packetsPerBox = watch("packetsPerBox");
  const boxesPerCarton = watch("boxesPerCarton");

  if (!open) return null;

  const totalPacketsPerCarton = (Number(packetsPerBox) || 0) * (Number(boxesPerCarton) || 0);

  const selectedWrapper = wrappers.find((w) => w.id === wrapperId);
  const selectedBox = boxes.find((b) => b.id === boxId);
  const costPerWrapper = selectedWrapper ? selectedWrapper.gramsPerUnit * costPerGram(selectedWrapper.rawMaterialId) : 0;
  const costPerBox = selectedBox ? selectedBox.gramsPerUnit * costPerGram(selectedBox.rawMaterialId) : 0;
  const costPerPacket = costPerWrapper;
  const costPerBoxAssembled = costPerBox + (Number(packetsPerBox) || 0) * costPerWrapper;
  const costPerCarton = (Number(boxesPerCarton) || 0) * costPerBoxAssembled;

  const onSubmit = async (values: CartonConfigFormValues) => {
    addCartonConfiguration(values);
    toast.success("Carton configuration created");
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">New Carton Configuration</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Configuration Name</label>
            <input {...register("name")} type="text" placeholder='e.g. "Carton A" or "Rs.5 Nimko 48pk"'
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.name && <p className="text-xs text-red-400 mt-1">{errors.name.message}</p>}
          </div>

          <div>
            <label className="text-sm text-[var(--text-muted)]">Wrapper</label>
            <Controller
              control={control}
              name="wrapperId"
              render={({ field }) => (
                <select {...field}
                  className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
                  <option value="">Select wrapper...</option>
                  {wrappers.map((w) => <option key={w.id} value={w.id}>{w.name}</option>)}
                </select>
              )}
            />
            {errors.wrapperId && <p className="text-xs text-red-400 mt-1">{errors.wrapperId.message}</p>}
          </div>

          <div>
            <label className="text-sm text-[var(--text-muted)]">Packets per Box</label>
            <input {...register("packetsPerBox")} type="number"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.packetsPerBox && <p className="text-xs text-red-400 mt-1">{errors.packetsPerBox.message}</p>}
          </div>

          <div>
            <label className="text-sm text-[var(--text-muted)]">Box</label>
            <Controller
              control={control}
              name="boxId"
              render={({ field }) => (
                <select {...field}
                  className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
                  <option value="">Select box...</option>
                  {boxes.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
                </select>
              )}
            />
            {errors.boxId && <p className="text-xs text-red-400 mt-1">{errors.boxId.message}</p>}
          </div>

          <div>
            <label className="text-sm text-[var(--text-muted)]">Boxes per Carton</label>
            <input {...register("boxesPerCarton")} type="number"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.boxesPerCarton && <p className="text-xs text-red-400 mt-1">{errors.boxesPerCarton.message}</p>}
          </div>

          {wrapperId && boxId && totalPacketsPerCarton > 0 && (
            <div className="rounded-lg border border-[var(--surface-border)] bg-[var(--background)] p-3 text-xs text-[var(--text-muted)]">
              {name?.trim() ? <span className="text-[var(--foreground)] font-medium">"{name.trim()}"</span> : "This configuration"} yields{" "}
              <span className="text-[var(--foreground)] font-medium">{totalPacketsPerCarton} packets</span> per carton.
            </div>
          )}

          {wrapperId && boxId && totalPacketsPerCarton > 0 && (
            <div className="rounded-lg border border-[var(--surface-border)] bg-[var(--background)] p-3 text-xs text-[var(--text-muted)] space-y-1.5">
              <div className="flex items-center text-[var(--foreground)] font-medium">
                Cost Build-Up
                <InfoTip text="Derived from each Wrapper/Box's grams-per-unit x its raw material's current weighted-average cost. Wrapper cost = per packet. Box cost + (Packets/Box x Wrapper cost) = per box. That x Boxes/Carton = per carton. Excludes bulk product cost, which varies per batch." />
              </div>
              <div className="grid grid-cols-2 gap-x-3 gap-y-1">
                <span>Cost / Wrapper (Packet)</span><span className="text-right text-[var(--foreground)]">Rs. {costPerPacket.toFixed(2)}</span>
                <span>Cost / Box</span><span className="text-right text-[var(--foreground)]">Rs. {costPerBox.toFixed(2)}</span>
                <span>Cost / Box (assembled)</span><span className="text-right text-[var(--foreground)]">Rs. {costPerBoxAssembled.toFixed(2)}</span>
                <span className="font-medium">Cost / Carton</span><span className="text-right text-[var(--foreground)] font-medium">Rs. {costPerCarton.toFixed(2)}</span>
              </div>
            </div>
          )}
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function CartonConfigPage() {
  const configs = useStore((s) => s.cartonConfigurations);
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const [dialogOpen, setDialogOpen] = useState(false);

  type Row = CartonConfiguration & { wrapperName: string; boxName: string; packetsPerCarton: number };

  const rows = useMemo<Row[]>(() => {
    return configs.map((c) => {
      const wrapper = wrappers.find((w) => w.id === c.wrapperId);
      const box = boxes.find((b) => b.id === c.boxId);
      return {
        ...c,
        wrapperName: wrapper?.name ?? "Unknown Wrapper",
        boxName: box?.name ?? "Unknown Box",
        packetsPerCarton: c.packetsPerBox * c.boxesPerCarton,
      };
    });
  }, [configs, wrappers, boxes]);

  const columns = useMemo<ColumnDef<Row, unknown>[]>(() => [
    { accessorKey: "name", header: "Name", cell: ({ getValue }) => <span className="text-[var(--foreground)] font-medium">{getValue() as string}</span> },
    { accessorKey: "wrapperName", header: "Wrapper" },
    { accessorKey: "packetsPerBox", header: "Packets / Box" },
    { accessorKey: "boxName", header: "Box" },
    { accessorKey: "boxesPerCarton", header: "Boxes / Carton" },
    { accessorKey: "packetsPerCarton", header: "Packets / Carton" },
    {
      id: "status", header: "Status", enableSorting: false,
      cell: ({ row }) => <StatusBadge used={row.original.usedInPackingRun} />,
    },
  ], []);

  const canCreate = wrappers.length > 0 && boxes.length > 0;

  return (
    <div className="space-y-6">
      <div className="text-sm text-[var(--text-muted)]">
        <a href="/packaging" className="hover:underline text-[var(--text-secondary)]">Packaging Materials</a>{" "}
        / <span className="text-[var(--foreground)]">Carton Configurations</span>
      </div>

      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Carton Configurations</h1>
        <button
          onClick={() => setDialogOpen(true)}
          disabled={!canCreate}
          title={canCreate ? undefined : "Add at least one Wrapper and one Box first"}
          className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50"
        >
          + New Configuration
        </button>
      </div>

      {!canCreate && (
        <div className="rounded-xl border border-amber-900 bg-amber-950 p-4 text-sm text-amber-400">
          You need at least one Wrapper and one Box before creating a carton configuration.
        </div>
      )}

      <SortableTable data={rows} columns={columns} globalFilterPlaceholder="Search configurations..." />
      <AddConfigDialog open={dialogOpen} onClose={() => setDialogOpen(false)} />
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type Wrapper, type Box, type RawMaterial } from "@/lib/store";
import {
  wrapperDefinitionSchema,
  boxDefinitionSchema,
  productionRunSchema,
  type WrapperDefinitionFormValues,
  type BoxDefinitionFormValues,
  type ProductionRunFormValues,
} from "@/lib/schemas";
import { SortableTable } from "@/components/ui/sortable-table";

function StatusBadge({ isLow }: { isLow: boolean }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
      isLow ? "bg-red-950 text-red-400 border border-red-900" : "bg-green-950 text-green-400 border border-green-900"
    }`}>
      {isLow ? "Low Stock" : "OK"}
    </span>
  );
}

function InfoTip({ text }: { text: string }) {
  return (
    <span
      title={text}
      className="ml-1 inline-flex h-4 w-4 items-center justify-center rounded-full border border-[var(--surface-border-strong)] text-[10px] leading-none text-[var(--text-muted)] cursor-help select-none align-middle"
    >
      i
    </span>
  );
}

type PackagingKind = "wrapper" | "box";

function DefineDialog({ kind, open, onClose }: { kind: PackagingKind; open: boolean; onClose: () => void }) {
  const rawMaterials = useStore((s) => s.rawMaterials);
  const addWrapper = useStore((s) => s.addWrapper);
  const addBox = useStore((s) => s.addBox);
  const schema = kind === "wrapper" ? wrapperDefinitionSchema : boxDefinitionSchema;

  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } = useForm<
    WrapperDefinitionFormValues | BoxDefinitionFormValues
  >({
    resolver: zodResolver(schema),
    defaultValues: {
      name: "",
      rawMaterialId: rawMaterials[0]?.id ?? "",
      gramsPerUnit: 0,
      lowStockThreshold: kind === "wrapper" ? 500 : 100,
    },
  });

  if (!open) return null;
  const label = kind === "wrapper" ? "Wrapper" : "Box";

  const onSubmit = async (values: WrapperDefinitionFormValues) => {
    if (kind === "wrapper") addWrapper(values);
    else addBox(values);
    toast.success(`${label} "${values.name}" defined`);
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Define {label}</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Name</label>
            <input {...register("name")} placeholder={kind === "wrapper" ? "e.g. Rs. 5 Wrapper" : "e.g. Box (12 packets)"}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.name && <p className="text-xs text-red-400 mt-1">{errors.name.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Underlying Raw Material</label>
            <select {...register("rawMaterialId")}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
              {rawMaterials.map((m: RawMaterial) => (
                <option key={m.id} value={m.id}>{m.name} ({m.unit})</option>
              ))}
            </select>
            {errors.rawMaterialId && <p className="text-xs text-red-400 mt-1">{errors.rawMaterialId.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)] inline-flex items-center">
              Grams per Unit
              <InfoTip text={`How many grams of the underlying raw material are used to make one ${label.toLowerCase()}`} />
            </label>
            <input {...register("gramsPerUnit")} type="number" step="any"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.gramsPerUnit && <p className="text-xs text-red-400 mt-1">{errors.gramsPerUnit.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Low Stock Threshold</label>
            <input {...register("lowStockThreshold")} type="number"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.lowStockThreshold && <p className="text-xs text-red-400 mt-1">{errors.lowStockThreshold.message}</p>}
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

type ProduceTarget = { kind: PackagingKind; item: Wrapper | Box } | null;

function ProduceDialog({ target, onClose }: { target: ProduceTarget; onClose: () => void }) {
  const rawMaterials = useStore((s) => s.rawMaterials);
  const produceWrapper = useStore((s) => s.produceWrapper);
  const produceBox = useStore((s) => s.produceBox);

  const { register, handleSubmit, reset, watch, formState: { errors, isSubmitting } } = useForm<ProductionRunFormValues>({
    resolver: zodResolver(productionRunSchema),
    defaultValues: { quantityProduced: 1 },
  });

  const quantityProducedRaw = watch("quantityProduced");
  const quantityProduced = Number(quantityProducedRaw) || 0;

  if (!target) return null;
  const { kind, item } = target;
  const rawMaterial = rawMaterials.find((m) => m.id === item.rawMaterialId);
  const unit = (rawMaterial?.unit ?? "").trim().toLowerCase();
  const multiplier = unit === "kg" || unit === "kilogram" || unit === "kilograms" ? 1000 : 1;
  const availableGrams = rawMaterial ? rawMaterial.quantityInStock * multiplier : 0;
  const gramsToConsume = item.gramsPerUnit * quantityProduced;
  const insufficient = gramsToConsume > availableGrams;

  const onSubmit = async (values: ProductionRunFormValues) => {
    const result = kind === "wrapper" ? produceWrapper(item.id, values.quantityProduced) : produceBox(item.id, values.quantityProduced);
    if (!result.ok) {
      toast.error(result.reason ?? "Could not complete production run");
      return;
    }
    toast.success(`Produced ${values.quantityProduced} x ${item.name}`);
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Produce: {item.name}</h2>

        <div className="rounded-lg border border-[var(--surface-border)] bg-[var(--background)] p-3 space-y-1 text-xs text-[var(--text-muted)]">
          <div className="flex justify-between">
            <span>Grams per Unit</span>
            <span className="text-[var(--foreground)]">{item.gramsPerUnit.toLocaleString()} g</span>
          </div>
          <div className="flex justify-between">
            <span>{rawMaterial?.name ?? "Raw material"} in stock</span>
            <span className="text-[var(--foreground)]">{availableGrams.toLocaleString()} g</span>
          </div>
        </div>

        <div>
          <label className="text-sm text-[var(--text-muted)]">Quantity to Produce</label>
          <input {...register("quantityProduced")} type="number" min={1}
            className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          {errors.quantityProduced && <p className="text-xs text-red-400 mt-1">{errors.quantityProduced.message}</p>}
        </div>

        <div className={`rounded-lg border p-3 text-xs ${insufficient ? "border-red-900 bg-red-950 text-red-400" : "border-[var(--surface-border)] bg-[var(--background)] text-[var(--text-muted)]"}`}>
          <div className="flex justify-between">
            <span>Grams to be consumed</span>
            <span className={insufficient ? "text-red-400 font-medium" : "text-[var(--foreground)] font-medium"}>
              {gramsToConsume.toLocaleString()} g
            </span>
          </div>
          {insufficient && (
            <p className="mt-1">Not enough {rawMaterial?.name ?? "raw material"} in stock to produce this quantity.</p>
          )}
        </div>

        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting || insufficient} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
            {isSubmitting ? "Producing..." : "Confirm"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function PackagingPage() {
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const rawMaterials = useStore((s) => s.rawMaterials);
  const wrapperUnitCost = useStore((s) => s.wrapperUnitCost);
  const boxUnitCost = useStore((s) => s.boxUnitCost);

  const [tab, setTab] = useState<"wrappers" | "boxes">("wrappers");
  const [defineOpen, setDefineOpen] = useState<PackagingKind | null>(null);
  const [produceTarget, setProduceTarget] = useState<ProduceTarget>(null);

  const materialName = (id: string) => rawMaterials.find((m) => m.id === id)?.name ?? "-";

  const wrapperColumns = useMemo<ColumnDef<Wrapper, unknown>[]>(() => [
    { accessorKey: "name", header: "Name", cell: ({ getValue }) => <span className="text-[var(--foreground)]">{getValue() as string}</span> },
    { id: "rawMaterial", header: "Underlying Raw Material", cell: ({ row }) => materialName(row.original.rawMaterialId) },
    { accessorKey: "gramsPerUnit", header: "Grams per Unit", cell: ({ getValue }) => `${(getValue() as number).toLocaleString()} g` },
    { id: "unitCost", header: "Derived Unit Cost", cell: ({ row }) => `Rs. ${wrapperUnitCost(row.original.id).toFixed(2)}` },
    { accessorKey: "stockQty", header: "Stock Qty", cell: ({ getValue }) => (getValue() as number).toLocaleString() },
    { accessorKey: "lowStockThreshold", header: "Threshold", cell: ({ getValue }) => (getValue() as number).toLocaleString() },
    {
      id: "status", header: "Status", enableSorting: false,
      cell: ({ row }) => <StatusBadge isLow={row.original.stockQty < row.original.lowStockThreshold} />,
    },
    {
      id: "action", header: "", enableSorting: false,
      cell: ({ row }) => (
        <button onClick={() => setProduceTarget({ kind: "wrapper", item: row.original })}
          className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-3 py-1.5 text-xs text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
          Produce
        </button>
      ),
    },
  ], [rawMaterials, wrapperUnitCost]);

  const boxColumns = useMemo<ColumnDef<Box, unknown>[]>(() => [
    { accessorKey: "name", header: "Name", cell: ({ getValue }) => <span className="text-[var(--foreground)]">{getValue() as string}</span> },
    { id: "rawMaterial", header: "Underlying Raw Material", cell: ({ row }) => materialName(row.original.rawMaterialId) },
    { accessorKey: "gramsPerUnit", header: "Grams per Unit", cell: ({ getValue }) => `${(getValue() as number).toLocaleString()} g` },
    { id: "unitCost", header: "Derived Unit Cost", cell: ({ row }) => `Rs. ${boxUnitCost(row.original.id).toFixed(2)}` },
    { accessorKey: "stockQty", header: "Stock Qty", cell: ({ getValue }) => (getValue() as number).toLocaleString() },
    { accessorKey: "lowStockThreshold", header: "Threshold", cell: ({ getValue }) => (getValue() as number).toLocaleString() },
    {
      id: "status", header: "Status", enableSorting: false,
      cell: ({ row }) => <StatusBadge isLow={row.original.stockQty < row.original.lowStockThreshold} />,
    },
    {
      id: "action", header: "", enableSorting: false,
      cell: ({ row }) => (
        <button onClick={() => setProduceTarget({ kind: "box", item: row.original })}
          className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-3 py-1.5 text-xs text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
          Produce
        </button>
      ),
    },
  ], [rawMaterials, boxUnitCost]);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Packaging Materials</h1>
        <div className="flex items-center gap-2">
          <NavLink href="/packaging/carton-config" className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
            Define Carton Configuration
          </NavLink>
          {tab === "wrappers" ? (
            <button onClick={() => setDefineOpen("wrapper")} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
              + Define Wrapper
            </button>
          ) : (
            <button onClick={() => setDefineOpen("box")} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
              + Define Box
            </button>
          )}
        </div>
      </div>

      <div className="flex gap-2 border-b border-[var(--surface-border)]">
        <button onClick={() => setTab("wrappers")} className={`px-4 py-2 text-sm font-medium border-b-2 ${tab === "wrappers" ? "border-neutral-900 dark:border-neutral-50 text-[var(--foreground)]" : "border-transparent text-[var(--text-muted)]"}`}>
          Wrappers
        </button>
        <button onClick={() => setTab("boxes")} className={`px-4 py-2 text-sm font-medium border-b-2 ${tab === "boxes" ? "border-neutral-900 dark:border-neutral-50 text-[var(--foreground)]" : "border-transparent text-[var(--text-muted)]"}`}>
          Boxes
        </button>
      </div>

      {tab === "wrappers" ? (
        <SortableTable data={wrappers} columns={wrapperColumns} globalFilterPlaceholder="Search wrappers..." />
      ) : (
        <SortableTable data={boxes} columns={boxColumns} globalFilterPlaceholder="Search boxes..." />
      )}

      <DefineDialog kind={defineOpen ?? "wrapper"} open={defineOpen !== null} onClose={() => setDefineOpen(null)} />
      <ProduceDialog target={produceTarget} onClose={() => setProduceTarget(null)} />
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useRouter } from "next/navigation";
import { useNavigationLoading } from "@/lib/navigation-loading-context";
import { useStore } from "@/lib/store";

function KpiCard({ label, value }: { label: string; value: string | number }) {
  return (
    <div className="bg-[var(--surface)] border border-[var(--surface-border)] rounded-xl p-4">
      <div className="text-[var(--text-muted)] text-sm">{label}</div>
      <div className="text-2xl font-semibold text-[var(--foreground)] mt-1">{value}</div>
    </div>
  );
}

export default function DashboardPage() {
  const router = useRouter();
  const { navigate } = useNavigationLoading();
  const rawMaterials = useStore((s) => s.rawMaterials);
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const invoices = useStore((s) => s.invoices);
  const finishedCartons = useStore((s) => s.finishedCartons);
  const customers = useStore((s) => s.customers);

  const lowStockItems = useMemo(() => {
    const rawAlerts = rawMaterials
      .filter((m) => m.quantityInStock < m.lowStockThreshold)
      .map((m) => ({ id: m.id, name: m.name, href: `/raw-materials/${m.id}`, qty: m.quantityInStock, threshold: m.lowStockThreshold }));
    const wrapperAlerts = wrappers
      .filter((w) => w.stockQty < w.lowStockThreshold)
      .map((w) => ({ id: w.id, name: w.name, href: `/packaging`, qty: w.stockQty, threshold: w.lowStockThreshold }));
    const boxAlerts = boxes
      .filter((b) => b.stockQty < b.lowStockThreshold)
      .map((b) => ({ id: b.id, name: b.name, href: `/packaging`, qty: b.stockQty, threshold: b.lowStockThreshold }));
    return [...rawAlerts, ...wrapperAlerts, ...boxAlerts];
  }, [rawMaterials, wrappers, boxes]);

  const kpis = useMemo(() => {
    const totalRawMaterialValue = rawMaterials.reduce((sum, m) => sum + m.quantityInStock * m.avgUnitCost, 0);
    const finishedCartonsReady = finishedCartons.reduce((sum, c) => sum + c.stockQty, 0);
    const totalReceivables = customers.reduce((sum, c) => sum + Math.max(0, c.currentBalance), 0);
    return { totalRawMaterialValue, finishedCartonsReady, totalReceivables };
  }, [rawMaterials, finishedCartons, customers]);

  const recentInvoices = invoices.slice(0, 5);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold">Dashboard</h1>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <KpiCard label="Total Raw Material Value" value={`Rs. ${kpis.totalRawMaterialValue.toLocaleString(undefined, { maximumFractionDigits: 0 })}`} />
        <KpiCard label="Batches This Month" value={6} />
        <KpiCard label="Finished Cartons Ready" value={kpis.finishedCartonsReady} />
        <KpiCard label="Total Receivables" value={`Rs. ${kpis.totalReceivables.toLocaleString()}`} />
      </div>

      <div className="flex flex-wrap gap-2">
        <NavLink href="/raw-materials" className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)] transition-colors">
          + Add Raw Material
        </NavLink>
        <button onClick={() => navigate("/batches/new")} className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)] transition-colors">
          + New Batch
        </button>
        <button onClick={() => navigate("/invoices/new")} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + New Invoice
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] overflow-hidden">
          <div className="px-4 py-3 border-b border-[var(--surface-border)]">
            <h2 className="text-sm font-semibold text-[var(--foreground)]">Low Stock Alerts</h2>
          </div>
          <div className="divide-y divide-[var(--surface-border)]">
            {lowStockItems.length === 0 && (
              <div className="px-4 py-6 text-center text-sm text-[var(--text-faint)]">All stock levels are healthy.</div>
            )}
            {lowStockItems.map((item) => (
              <NavLink key={item.id} href={item.href} className="flex items-center justify-between px-4 py-3 hover:bg-[var(--surface-hover)]/60">
                <span className="text-sm text-[var(--foreground)]">{item.name}</span>
                <span className="text-xs text-red-400">{item.qty} / {item.threshold}</span>
              </NavLink>
            ))}
          </div>
        </div>

        <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] overflow-hidden">
          <div className="px-4 py-3 border-b border-[var(--surface-border)] flex items-center justify-between">
            <h2 className="text-sm font-semibold text-[var(--foreground)]">Recent Invoices</h2>
            <NavLink href="/invoices" className="text-xs text-[var(--text-muted)] hover:text-[var(--foreground)] hover:underline">View all</NavLink>
          </div>
          <table className="w-full text-sm">
            <tbody>
              {recentInvoices.map((inv) => (
                <tr key={inv.id} className="border-b border-[var(--surface-border)] last:border-0">
                  <td className="px-4 py-3">
                    <NavLink href={`/invoices/${inv.id}`} className="text-[var(--foreground)] hover:underline">{inv.id}</NavLink>
                  </td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">{inv.customerName}</td>
                  <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {inv.totalAmount.toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type Payment } from "@/lib/store";
import { paymentSchema, type PaymentFormValues } from "@/lib/schemas";
import { SortableTable } from "@/components/ui/sortable-table";

function RecordPaymentDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const customers = useStore((s) => s.customers);
  const recordLedgerEntry = useStore((s) => s.recordLedgerEntry);
  const {
    register,
    handleSubmit,
    reset,
    watch,
    setValue,
    formState: { errors, isSubmitting },
  } = useForm<PaymentFormValues>({
    resolver: zodResolver(paymentSchema),
    defaultValues: { customerId: customers[0]?.id ?? "", amount: 0, direction: "received", note: "" },
  });
  const direction = watch("direction");

  if (!open) return null;

  const onSubmit = async (values: PaymentFormValues) => {
    recordLedgerEntry(values.customerId, values.amount, values.direction, values.note ?? "");
    toast.success(
      values.direction === "received"
        ? `Payment of Rs. ${values.amount.toLocaleString()} received`
        : `Rs. ${values.amount.toLocaleString()} recorded as given / credit adjustment`
    );
    reset();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Record Payment</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Customer</label>
            <select {...register("customerId")}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
              {customers.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            {errors.customerId && <p className="text-xs text-red-400 mt-1">{errors.customerId.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Amount</label>
            <input {...register("amount")} type="number" step="any"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.amount && <p className="text-xs text-red-400 mt-1">{errors.amount.message}</p>}
          </div>
          <div>
            <div className="flex items-center gap-1.5">
              <label className="text-sm text-[var(--text-muted)]">Direction</label>
              <span
                title='Received = payment received from customer, reduces what they owe. Given = amount given to customer (refund) or a credit adjustment in their favor.'
                className="flex h-3.5 w-3.5 cursor-help items-center justify-center rounded-full border border-[var(--text-faint)] text-[9px] leading-none text-[var(--text-faint)]"
              >
                i
              </span>
            </div>
            <div className="mt-1 grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => setValue("direction", "received", { shouldValidate: true })}
                className={`rounded-lg border px-3 py-2 text-xs font-medium transition-colors ${
                  direction === "received"
                    ? "border-green-500 bg-green-500/10 text-green-400"
                    : "border-[var(--surface-border)] text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]"
                }`}
              >
                + Received from customer
              </button>
              <button
                type="button"
                onClick={() => setValue("direction", "given", { shouldValidate: true })}
                className={`rounded-lg border px-3 py-2 text-xs font-medium transition-colors ${
                  direction === "given"
                    ? "border-red-500 bg-red-500/10 text-red-400"
                    : "border-[var(--surface-border)] text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]"
                }`}
              >
                âˆ’ Given / credit adjustment
              </button>
            </div>
            <input type="hidden" {...register("direction")} />
            {errors.direction && <p className="text-xs text-red-400 mt-1">{errors.direction.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Note</label>
            <input {...register("note")} placeholder='e.g. "cash refund", "damaged stock credit"'
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:bg-neutral-200 disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function PaymentsPage() {
  const items = useStore((s) => s.payments);
