"use client";

import React, { useState } from "react";
import { usePathname } from "next/navigation";
import {
  Search as SearchIcon,
  Dashboard,
  Task,
  Folder,
  UserMultiple,
  Analytics,
  DocumentAdd,
  Settings as SettingsIcon,
