const softSpringEasing = "cubic-bezier(0.25, 1.1, 0.4, 1)";

type SectionId =
  | "dashboard"
  | "suppliers"
  | "raw-materials"
  | "receipts"
  | "batches"
  | "finished-cartons"
  | "customers"
  | "invoices"
  | "payments"
  | "reports"
  | "settings";

