  dashboard: "/",
  suppliers: "/suppliers",
  "raw-materials": "/raw-materials",
  receipts: "/receipts",
  batches: "/batches",
  "finished-cartons": "/finished-cartons",
  customers: "/customers",
  invoices: "/invoices",
  payments: "/payments",
  reports: "/reports",
  settings: "/settings",
};

const ROUTE_PREFIXES: Array<[string, SectionId]> = [
  ["/suppliers", "suppliers"],
  ["/raw-materials", "raw-materials"],
  ["/receipts", "receipts"],
  ["/packaging", "raw-materials"],
  ["/packaging/carton-config", "raw-materials"],
  ["/batches", "batches"],
  ["/finished-cartons", "finished-cartons"],
  ["/customers", "customers"],
  ["/invoices", "invoices"],
  ["/payments", "payments"],
  ["/reports", "reports"],
  ["/settings", "settings"],
];

function getSectionFromPathname(pathname: string): SectionId {
  for (const [prefix, section] of ROUTE_PREFIXES) {
    if (pathname === prefix || pathname.startsWith(prefix + "/")) return section;
  }
  return "dashboard";
