            </div>
            <div className="max-h-72 overflow-y-auto">
              {alerts.length === 0 && (
                <div className="px-4 py-6 text-center text-sm text-[var(--text-faint)]">All stock levels are healthy.</div>
              )}
              {alerts.map((a) => (
                <NavLink
                  key={a.id}
                  href={a.href}
                  onClick={() => setOpen(false)}
